import org.sireum._
import art.Art
import eit_acquisition_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait CollectionFeasibilityOwner_acquisition_process_collection_feasibility_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility)
  }

  /** helper function to set the values of all input ports.
   * @param recovery_frame payload for data port recovery_frame
   * @param session_frame payload for data port session_frame
   * @param cycle_frame payload for data port cycle_frame
   */
  def put_concrete_inputs(recovery_frame : EIT_Acquisition_Supervisor.RecoveryFrame,
                          session_frame : EIT_Acquisition_Supervisor.SessionFrame,
                          cycle_frame : EIT_Acquisition_Supervisor.CycleFrame): Unit = {
    put_recovery_frame(recovery_frame)
    put_session_frame(session_frame)
    put_cycle_frame(cycle_frame)
  }


  /** helper function to check CollectionFeasibilityOwner_acquisition_process_collection_feasibility's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param collection_proposal method that will be called with the value of the outgoing data
   *        port 'collection_proposal'.
   */
  def check_concrete_output(collection_proposal: EIT_Acquisition_Supervisor.Proposal.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val collection_proposalValue: EIT_Acquisition_Supervisor.Proposal.Type = get_collection_proposal().get
    if(!collection_proposal(collection_proposalValue)) {
      testFailures = testFailures :+ st"'collection_proposal' did not match expected: value of the outgoing data port is ${collection_proposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recovery_frame(value : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.operational_api.recovery_frame_Id, EIT_Acquisition_Supervisor.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_session_frame(value : EIT_Acquisition_Supervisor.SessionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.operational_api.session_frame_Id, EIT_Acquisition_Supervisor.SessionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_cycle_frame(value : EIT_Acquisition_Supervisor.CycleFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.operational_api.cycle_frame_Id, EIT_Acquisition_Supervisor.CycleFrame_Payload(value))
  }

  // getter for out DataPort
  def get_collection_proposal(): Option[EIT_Acquisition_Supervisor.Proposal.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.Proposal.Type] = get_collection_proposal_payload() match {
      case Some(EIT_Acquisition_Supervisor.Proposal_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port collection_proposal.  Expecting 'EIT_Acquisition_Supervisor.Proposal_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.Proposal.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_collection_proposal_payload(): Option[EIT_Acquisition_Supervisor.Proposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.initialization_api.collection_proposal_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.Proposal_Payload]]
  }

}
